function getRecomendacionClass(puntaje) {
  if (puntaje >= 7) return 'contratar';
  if (puntaje > 5) return 'considerar';
  return 'no-recomendable';
}

function getRecomendacionText(puntaje) {
  if (puntaje >= 7) return 'Contratar';
  if (puntaje > 5) return 'Considerar';
  return 'No Recomendable';
}

function getBadgeColor(puntaje) {
  if (puntaje >= 7) return '#10b981';
  if (puntaje > 5) return '#f59e0b';
  return '#ef4444';
}

function generarLinkSupabase(nombre, telefono) {
  if (!telefono || !nombre) return null;
  const nombreLimpio = nombre.trim();
  const telefonoLimpio = telefono.trim();
  const nombreArchivo = `${nombreLimpio}${telefonoLimpio}.pdf`;
  const nombreDescarga = encodeURIComponent(nombreArchivo);
  return `${SUPABASE_URL}/storage/v1/object/public/cvs/${nombreDescarga}?download=${nombreArchivo}`;
}

function escapeHtml(text) {
  if (!text) return '';
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;')
    .replace(/\n/g, ' ')
    .replace(/\r/g, '');
}

